def test_no_rows_gives_empty_prices() -> None:
    assert align_calendar([]) == Prices(dates=(), tickers=(), closes={})


def test_ticker_with_no_close_gives_no_dates() -> None:
    rows = [
        RawRow(date="2025-03-03", ticker="AAA", close=1.0),
        RawRow(date="2025-03-03", ticker="BBB", close=None),
    ]
    assert align_calendar(rows) == Prices(
        dates=(), tickers=("AAA", "BBB"), closes={"AAA": (), "BBB": ()}
    )


def test_earlier_starter_carries_its_close_onto_the_start_date() -> None:
    rows = [
        RawRow(date="2025-03-03", ticker="AAA", close=1.0),
        RawRow(date="2025-03-04", ticker="BBB", close=7.0),
        RawRow(date="2025-03-05", ticker="AAA", close=3.0),
        RawRow(date="2025-03-05", ticker="BBB", close=8.0),
    ]
    result = align_calendar(rows)
    assert result.dates == ("2025-03-04", "2025-03-05")
    assert result.closes == {"AAA": (1.0, 3.0), "BBB": (7.0, 8.0)}


def test_trailing_missing_dates_take_last_close() -> None:
    rows = [
        RawRow(date="2025-03-03", ticker="AAA", close=1.0),
        RawRow(date="2025-03-03", ticker="BBB", close=4.0),
        RawRow(date="2025-03-04", ticker="AAA", close=2.0),
        RawRow(date="2025-03-05", ticker="AAA", close=3.0),
    ]
    assert align_calendar(rows).closes == {"AAA": (1.0, 2.0, 3.0), "BBB": (4.0, 4.0, 4.0)}


def _gap_rows(missing: int) -> list[RawRow]:
    days = [f"2025-04-{day:02d}" for day in range(1, missing + 3)]
    rows = [RawRow(date=day, ticker="AAA", close=1.0) for day in days]
    rows += [
        RawRow(date=days[0], ticker="ZZZ", close=9.0),
        RawRow(date=days[-1], ticker="ZZZ", close=10.0),
    ]
    return rows


def test_gap_of_max_gap_dates_is_filled() -> None:
    assert align_calendar(_gap_rows(2), max_gap=2).closes["ZZZ"] == (9.0, 9.0, 9.0, 10.0)


def test_gap_over_max_gap_raises_naming_the_ticker() -> None:
    with pytest.raises(GapError, match="ZZZ"):
        align_calendar(_gap_rows(3), max_gap=2)


def test_trailing_gap_over_max_gap_raises() -> None:
    rows = [RawRow(date="2025-04-01", ticker="ZZZ", close=9.0)]
    rows += [RawRow(date=f"2025-04-0{day}", ticker="AAA", close=1.0) for day in range(1, 4)]
    with pytest.raises(GapError, match="ZZZ"):
        align_calendar(rows, max_gap=1)

